<?php $idSeccion=(int)($_GET['idSeccion']??0);if(!ControladorAsistencias::crtPuedeGestionar($idSeccion)){echo '<section class="content"><div class="empty-state"><i class="fas fa-lock"></i><h4>No tenés acceso a esta asistencia</h4></div></section>';return;}$seccion=ControladorLecciones::crtBuscarSeccionPorId($idSeccion);$clases=ControladorAsistencias::crtClases($idSeccion);$idClase=(int)($_GET['idClase']??($clases[0]['idClase']??0));$clase=$idClase?ControladorAsistencias::crtClase($idClase):null;if($clase&&(int)$clase['id_seccion']!==$idSeccion){$clase=null;}$registros=$clase?ControladorAsistencias::crtRegistros($idClase):[];$resumenEstudiantes=[];foreach(ControladorAsistencias::crtResumenEstudiantesSeccion($idSeccion) as $resumen){$resumenEstudiantes[(int)$resumen['id_estudiante']]=$resumen;}$fechaReferencia=$clase['fechaClase']??($clases[0]['fechaClase']??date('Y-m-d'));$anioReferencia=date('Y',strtotime($fechaReferencia));$mesReferencia=date('m',strtotime($fechaReferencia));$anios=[];foreach($clases as $itemClase){$anios[date('Y',strtotime($itemClase['fechaClase']))]=true;}$e=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};?>
<section class="content page-fade"><div class="container-fluid"><div class="entity-hero mb-4"><div class="entity-hero__content"><span class="entity-kicker mb-3"><?php echo $e($seccion['nombreCurso']??'Curso');?></span><h1 class="entity-title mb-2">Asistencia de <?php echo $e($seccion['tituloSeccion']??'Materia');?></h1><p class="entity-lead mb-0">Creá una fecha y modificá solamente las excepciones.</p></div></div>
<div class="card glass-card mb-4"><div class="card-header section-header-soft"><h3 class="card-title mb-0">Nueva clase</h3></div><div class="card-body"><form method="post" class="form-row align-items-end"><input type="hidden" name="accion_asistencia" value="crear_clase"><input type="hidden" name="id_seccion" value="<?php echo $idSeccion;?>"><div class="form-group col-md-3"><label>Fecha</label><input class="form-control" type="date" name="fechaClase" value="<?php echo date('Y-m-d');?>" required></div><div class="form-group col-md-7"><label>Tema u observación general</label><input class="form-control" name="tema" maxlength="180" placeholder="Opcional"></div><div class="form-group col-md-2"><button class="btn btn-primary btn-block"><i class="fas fa-plus mr-1"></i>Tomar asistencia</button></div></form></div></div>
<div class="row"><div class="col-lg-3 mb-3"><div class="card glass-card attendance-history"><div class="card-header"><h3 class="card-title mb-2">Clases</h3><input type="search" class="form-control form-control-sm mb-2" placeholder="Buscar fecha o tema..." data-attendance-search><div class="form-row"><div class="col-5"><select class="form-control form-control-sm" data-attendance-year><option value="">Todos</option><?php foreach(array_keys($anios) as $anio):?><option value="<?php echo $anio;?>" <?php echo $anio===$anioReferencia?'selected':'';?>><?php echo $anio;?></option><?php endforeach;?></select></div><div class="col-7"><select class="form-control form-control-sm" data-attendance-month><option value="">Todos los meses</option><?php foreach(['01'=>'Enero','02'=>'Febrero','03'=>'Marzo','04'=>'Abril','05'=>'Mayo','06'=>'Junio','07'=>'Julio','08'=>'Agosto','09'=>'Septiembre','10'=>'Octubre','11'=>'Noviembre','12'=>'Diciembre'] as $numero=>$nombre):?><option value="<?php echo $numero;?>" <?php echo $numero===$mesReferencia?'selected':'';?>><?php echo $nombre;?></option><?php endforeach;?></select></div></div></div><div class="list-group list-group-flush" data-attendance-list><?php foreach($clases as $c):?><a data-attendance-item data-year="<?php echo date('Y',strtotime($c['fechaClase']));?>" data-month="<?php echo date('m',strtotime($c['fechaClase']));?>" data-search="<?php echo $e(date('d/m/Y',strtotime($c['fechaClase'])).' '.($c['tema']??''));?>" class="list-group-item list-group-item-action <?php echo (int)$c['idClase']===$idClase?'active':'';?>" href="index.php?r=asistencia-seccion&amp;idSeccion=<?php echo $idSeccion;?>&amp;idClase=<?php echo (int)$c['idClase'];?>"><strong><?php echo date('d/m/Y',strtotime($c['fechaClase']));?></strong><?php if(!empty($c['tema'])):?><small class="d-block text-truncate <?php echo (int)$c['idClase']===$idClase?'text-white':'text-muted';?>"><?php echo $e($c['tema']);?></small><?php endif;?><small class="d-block <?php echo (int)$c['idClase']===$idClase?'text-white':'text-muted';?>"><?php echo (int)$c['presentes'];?> presentes · <?php echo (int)$c['ausentes'];?> ausentes</small></a><?php endforeach;?><div class="p-3 text-muted d-none" data-attendance-empty>No hay clases para este filtro.</div></div></div></div>
<div class="col-lg-9"><?php if(!$clase):?><div class="card glass-card"><div class="empty-state"><i class="fas fa-calendar-plus"></i><h4>Creá la primera clase</h4><p>Todos los estudiantes quedarán presentes por defecto.</p></div></div><?php else:?><form method="post" class="card glass-card"><input type="hidden" name="accion_asistencia" value="guardar_asistencia"><input type="hidden" name="id_seccion" value="<?php echo $idSeccion;?>"><input type="hidden" name="id_clase" value="<?php echo $idClase;?>"><div class="card-header section-header-soft d-flex justify-content-between"><div><h3 class="card-title mb-1"><?php echo date('d/m/Y',strtotime($clase['fechaClase']));?></h3><small><?php echo $e($clase['tema']);?></small></div><button class="btn btn-success btn-sm"><i class="fas fa-save mr-1"></i>Guardar asistencia</button></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Estudiante</th><th style="width:190px">Estado</th><th>Observación</th></tr></thead><tbody><?php foreach($registros as $r):$acumulado=$resumenEstudiantes[(int)$r['id_estudiante']]??[];?><tr><td><strong><?php echo $e($r['apellidoUsuario'].' '.$r['nombreUsuario']);?></strong><small class="d-block text-muted"><span class="text-danger font-weight-bold"><?php echo (int)($acumulado['ausentes']??0);?> faltas</span> · <?php echo (int)($acumulado['tardanzas']??0);?> tardanzas · <?php echo (int)($acumulado['justificadas']??0);?> justificadas</small></td><td><select class="form-control form-control-sm attendance-state" name="estados[<?php echo (int)$r['id_estudiante'];?>]"><?php foreach(['PRESENTE'=>'Presente','AUSENTE'=>'Ausente','TARDANZA'=>'Tardanza','JUSTIFICADA'=>'Justificada'] as $v=>$label):?><option value="<?php echo $v;?>" <?php echo $r['estado']===$v?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select></td><td><input class="form-control form-control-sm" name="observaciones[<?php echo (int)$r['id_estudiante'];?>]" value="<?php echo $e($r['observacion']);?>" maxlength="255" placeholder="Opcional"></td></tr><?php endforeach;?></tbody></table></div></form><?php endif;?></div></div></div></section>
<script>document.addEventListener('DOMContentLoaded',function(){var search=document.querySelector('[data-attendance-search]'),year=document.querySelector('[data-attendance-year]'),month=document.querySelector('[data-attendance-month]'),items=[].slice.call(document.querySelectorAll('[data-attendance-item]')),empty=document.querySelector('[data-attendance-empty]');function filter(){var q=(search.value||'').toLowerCase().trim(),visible=0;items.forEach(function(item){var show=(!year.value||item.dataset.year===year.value)&&(!month.value||item.dataset.month===month.value)&&(!q||(item.dataset.search||'').toLowerCase().indexOf(q)!==-1);item.classList.toggle('d-none',!show);if(show)visible++;});if(empty)empty.classList.toggle('d-none',visible>0);}if(search){search.addEventListener('input',filter);year.addEventListener('change',filter);month.addEventListener('change',filter);filter();}});</script>
